(.day-cycle){border:0}.service-access:focus-visible{outline:3px solid #6c813f;outline-offset:4px}@media(max-width:1100px){.controller-rail{grid-template-columns:1fr auto auto;gap:18px}.rhythm-heading{grid-template-columns:170px 1fr;gap:16px}.provenance{grid-column:1/-1;max-width:none;display:flex;justify-content:space-between;align-items:center;text-align:left}}@media(max-width:700px){.controller-rail{grid-template-columns:minmax(0,1fr) auto;gap:15px;padding:14px 15px}.living-overview .controller-name h2{font-size:21px}.controller-name h2 small{font-size:9px}.controller-readback{grid-column:1/-1;grid-row:2;border-top:1px solid #b2bf98;padding-top:10px;font-size:11px}.controller-readback span{font-size:10px}.service-access{grid-column:2;grid-row:1;padding-left:12px}.service-access>span{font-size:10px}.service-access strong{font-size:13px}.service-access small{display:block;margin-left:0}.rhythm-heading{grid-template-columns:1fr;gap:12px;padding:18px 15px 0}.rhythm-heading label{font-size:11px}.rhythm-heading select{font-size:16px;max-width:none}.provenance{font-size:10px;gap:14px;max-width:none}.provenance{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 14px}.provenance>span{grid-column:1/-1}.provenance a{font-size:11px;text-align:left}.rhythm-heading .plan-refresh{margin-left:0;white-space:nowrap}.rhythm-unavailable{padding:18px 15px}.rhythm-unavailable strong{font-size:16px}.draft-note{padding:12px 15px}}
</style>
